// Get incoming data from the Webhook
const input = $input.first().json;

// Voiceflow may send submitted data inside "body".
let body = input.body ?? input;

if (typeof body === "string") {
  try {
    body = JSON.parse(body);
  } catch {
    throw new Error(
      "The submitted tour-request data could not be read."
    );
  }
}

if (!body || typeof body !== "object") {
  throw new Error(
    "The submitted tour-request data is missing or invalid."
  );
}


// Clean required text fields
function clean(
  value,
  defaultValue = "Not specified"
) {
  if (
    value === undefined ||
    value === null
  ) {
    return defaultValue;
  }

  const text = String(value).trim();

  return text === ""
    ? defaultValue
    : text;
}


// Clean optional fields
function cleanOptional(
  value,
  defaultValue = "Not specified"
) {
  if (
    value === undefined ||
    value === null
  ) {
    return defaultValue;
  }

  const text = String(value).trim();

  if (
    text === "" ||
    text === "0"
  ) {
    return defaultValue;
  }

  return text;
}


// Preserve phone number exactly as received
function preservePhone(
  value,
  defaultValue = "Not specified"
) {
  if (
    value === undefined ||
    value === null
  ) {
    return defaultValue;
  }

  const phone = String(value);

  return phone.trim() === ""
    ? defaultValue
    : phone;
}


// Validate and lowercase required email
function cleanEmail(value) {
  const cleaned = clean(value);

  if (cleaned === "Not specified") {
    throw new Error(
      "A valid email address is required. The tour request was not saved."
    );
  }

  const email = cleaned.toLowerCase();

  if (email.length > 254) {
    throw new Error(
      "The email address is too long. The tour request was not saved."
    );
  }

  if (/\s/.test(email)) {
    throw new Error(
      "The email address contains spaces. The tour request was not saved."
    );
  }

  const parts = email.split("@");

  if (parts.length !== 2) {
    throw new Error(
      "The email address must contain exactly one @ symbol. The tour request was not saved."
    );
  }

  const [localPart, domain] = parts;

  if (!localPart || !domain) {
    throw new Error(
      "The email address is incomplete. The tour request was not saved."
    );
  }

  if (localPart.length > 64) {
    throw new Error(
      "The email address is invalid. The tour request was not saved."
    );
  }

  if (
    localPart.startsWith(".") ||
    localPart.endsWith(".") ||
    localPart.includes("..") ||
    domain.includes("..")
  ) {
    throw new Error(
      "The email address contains an invalid period placement. The tour request was not saved."
    );
  }

  const validLocalPart =
    /^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/i;

  if (!validLocalPart.test(localPart)) {
    throw new Error(
      "The email address contains an unsupported character. The tour request was not saved."
    );
  }

  if (!domain.includes(".")) {
    throw new Error(
      "The email domain is incomplete. The tour request was not saved."
    );
  }

  const domainParts = domain.split(".");

  for (const domainPart of domainParts) {
    if (
      !domainPart ||
      domainPart.length > 63 ||
      !/^[a-z0-9-]+$/i.test(domainPart) ||
      domainPart.startsWith("-") ||
      domainPart.endsWith("-")
    ) {
      throw new Error(
        "The email domain is invalid. The tour request was not saved."
      );
    }
  }

  const topLevelDomain =
    domainParts[domainParts.length - 1];

  if (!/^[a-z]{2,63}$/i.test(topLevelDomain)) {
    throw new Error(
      "The email domain ending is invalid. The tour request was not saved."
    );
  }

  return email;
}


// Validate IANA timezone
function validateTimezone(timezone) {
  try {
    new Intl.DateTimeFormat("en-US", {
      timeZone: timezone
    }).format(new Date());

    return timezone;
  } catch {
    throw new Error(
      `The tour timezone "${timezone}" is invalid. The request was not saved.`
    );
  }
}


// Return date/time parts for a timestamp in a timezone
function getTimezoneParts(
  timestamp,
  timezone
) {
  const parts =
    new Intl.DateTimeFormat("en-GB", {
      timeZone: timezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false,
      hourCycle: "h23"
    }).formatToParts(new Date(timestamp));

  function getValue(type) {
    const part = parts.find(
      (item) => item.type === type
    );

    return part
      ? Number(part.value)
      : NaN;
  }

  return {
    year: getValue("year"),
    month: getValue("month"),
    day: getValue("day"),
    hour: getValue("hour"),
    minute: getValue("minute"),
    second: getValue("second")
  };
}


// Convert local YYYY-MM-DD and HH:mm into UTC
function localDateTimeToUtc(
  dateInput,
  timeInput,
  timezone,
  fieldLabel
) {
  const date = clean(dateInput);
  const time = clean(timeInput);

  if (
    date === "Not specified" ||
    time === "Not specified"
  ) {
    throw new Error(
      `${fieldLabel} date and time are required.`
    );
  }

  const dateMatch =
    /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);

  if (!dateMatch) {
    throw new Error(
      `${fieldLabel} date must use YYYY-MM-DD format.`
    );
  }

  const timeMatch =
    /^([01]\d|2[0-3]):([0-5]\d)$/.exec(time);

  if (!timeMatch) {
    throw new Error(
      `${fieldLabel} time must use 24-hour HH:mm format.`
    );
  }

  const year = Number(dateMatch[1]);
  const month = Number(dateMatch[2]);
  const day = Number(dateMatch[3]);
  const hour = Number(timeMatch[1]);
  const minute = Number(timeMatch[2]);

  const calendarCheck = new Date(
    Date.UTC(year, month - 1, day)
  );

  if (
    calendarCheck.getUTCFullYear() !== year ||
    calendarCheck.getUTCMonth() !== month - 1 ||
    calendarCheck.getUTCDate() !== day
  ) {
    throw new Error(
      `${fieldLabel} contains an invalid calendar date.`
    );
  }

  const desiredAsUtc = Date.UTC(
    year,
    month - 1,
    day,
    hour,
    minute,
    0
  );

  let requestedTimestamp = desiredAsUtc;

  // Adjust repeatedly until the timestamp displays
  // as the requested local date/time in the timezone.
  for (
    let attempt = 0;
    attempt < 4;
    attempt += 1
  ) {
    const observed = getTimezoneParts(
      requestedTimestamp,
      timezone
    );

    const observedAsUtc = Date.UTC(
      observed.year,
      observed.month - 1,
      observed.day,
      observed.hour,
      observed.minute,
      0
    );

    requestedTimestamp +=
      desiredAsUtc - observedAsUtc;
  }

  const verified = getTimezoneParts(
    requestedTimestamp,
    timezone
  );

  if (
    verified.year !== year ||
    verified.month !== month ||
    verified.day !== day ||
    verified.hour !== hour ||
    verified.minute !== minute
  ) {
    throw new Error(
      `${fieldLabel} does not exist in timezone ${timezone}.`
    );
  }

  return new Date(
    requestedTimestamp
  ).toISOString();
}


// Calculate optional alternative UTC timestamp
function calculateAlternativeUtc(
  alternativeDate,
  alternativeTime,
  timezone
) {
  const date = cleanOptional(
    alternativeDate
  );

  const time = cleanOptional(
    alternativeTime
  );

  if (
    date === "Not specified" &&
    time === "Not specified"
  ) {
    return "Not specified";
  }

  if (
    date === "Not specified" ||
    time === "Not specified"
  ) {
    throw new Error(
      "The alternative tour date and time must either both be provided or both be Not specified."
    );
  }

  return localDateTimeToUtc(
    date,
    time,
    timezone,
    "Alternative tour"
  );
}


// Read and validate timezone
const requestedTimeTimezone =
  validateTimezone(
    clean(body.requested_time_timezone)
  );


// Clean tour dates and times
const preferredDate = clean(
  body.preferred_date
);

const preferredTime = clean(
  body.preferred_time
);

const alternativeDate = cleanOptional(
  body.alternative_date
);

const alternativeTime = cleanOptional(
  body.alternative_time
);


// Calculate UTC timestamps directly in n8n
const preferredDatetimeUtc =
  localDateTimeToUtc(
    preferredDate,
    preferredTime,
    requestedTimeTimezone,
    "Preferred tour"
  );

const alternativeDatetimeUtc =
  calculateAlternativeUtc(
    alternativeDate,
    alternativeTime,
    requestedTimeTimezone
  );


// Generate submission date and timestamp.
// Prefer a supplied business timezone; fall back to the requested tour timezone.
const submissionTimezone = validateTimezone(
  cleanOptional(
    body.business_timezone,
    requestedTimeTimezone
  )
);

const now = new Date();

const submissionParts =
  new Intl.DateTimeFormat("en-GB", {
    timeZone: submissionTimezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
    hourCycle: "h23"
  }).formatToParts(now);

const getSubmissionPart = (type) =>
  submissionParts.find(
    (part) => part.type === type
  )?.value;

const year = getSubmissionPart("year");
const month = getSubmissionPart("month");
const day = getSubmissionPart("day");
const hour = getSubmissionPart("hour");
const minute = getSubmissionPart("minute");
const second = getSubmissionPart("second");

const dateSubmitted =
  `${year}-${month}-${day}`;

const timestamp =
  `${dateSubmitted} ${hour}:${minute}:${second}`;


// Generate unique tour-request ID
const randomPart = Math.random()
  .toString(36)
  .slice(2, 8)
  .toUpperCase();

const tourRequestId =
  `TOUR-${year}${month}${day}-${Date.now()}-${randomPart}`;


// Return normalized tour data
return [
  {
    json: {
      tour_request_id: tourRequestId,

      name: clean(
        body.name
      ),

      phone: preservePhone(
        body.phone
      ),

      email: cleanEmail(
        body.email
      ),

      visitor_type: clean(
        body.visitor_type
      ),

      tour_type: cleanOptional(
        body.tour_type,
        "Model Home Tour"
      ),

      community: clean(
        body.community
      ),

      property: clean(
        body.property
      ),

      preferred_date: preferredDate,

      preferred_time: preferredTime,

      preferred_datetime_utc:
        preferredDatetimeUtc,

      alternative_date:
        alternativeDate,

      alternative_time:
        alternativeTime,

      alternative_datetime_utc:
        alternativeDatetimeUtc,

      requested_time_timezone:
        requestedTimeTimezone,

      number_of_guests: cleanOptional(
        body.number_of_guests
      ),

      special_instructions: cleanOptional(
        body.special_instructions
      ),

      preferred_contact_method: clean(
        body.preferred_contact_method
      ),

      booking_status: "Pending",

      submission_timezone: submissionTimezone,

      date_submitted: dateSubmitted,

      timestamp
    }
  }
];
